package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;

/**
 * Unit tests for NullifyingDeserializer#deserialize
 */
public class NullifyingDeserializer_deserialize_TriageGen2Test {

    private NullifyingDeserializer deserializer;
    private JsonParser p;
    private DeserializationContext ctxt;

    @Before
    public void setUp() {
        deserializer = new NullifyingDeserializer();
        p = mock(JsonParser.class);
        ctxt = mock(DeserializationContext.class);
    }

    @Test
    public void testDeserialize_ReturnsNullAndSkipsChildren() throws IOException {
        // Execute
        Object result = deserializer.deserialize(p, ctxt);

        // Verify return value is null
        assertNull("The deserializer should return null", result);

        // Verify that skipChildren() was called once
        verify(p, times(1)).skipChildren();
    }


}

package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;

/**
 * Unit tests for NullifyingDeserializer#deserialize
 */
public class NullifyingDeserializer_deserialize_TriageGen2Test {

    private NullifyingDeserializer deserializer;
    private JsonParser p;
    private DeserializationContext ctxt;

    @Before
    public void setUp() {
        deserializer = new NullifyingDeserializer();
        p = mock(JsonParser.class);
        ctxt = mock(DeserializationContext.class);
    }



    @Test
    public void testDeserialize_ThrowsIOExceptionWhenParserFails() throws IOException {
        // Setup: Force skipChildren to throw an IOException
        Mockito.doThrow(new IOException("Simulated IO Error")).when(p).skipChildren();

        // Execute & Verify
        try {
            deserializer.deserialize(p, ctxt);
            org.junit.Assert.fail("Expected IOException to be thrown");
        } catch (IOException e) {
            org.junit.Assert.assertEquals("Simulated IO Error", e.getMessage());
        }
    }
}
